shelfLow=150;
shelfHigh=2000;
shelfSpacing=50;
/* maximum number of sections in D and W, must be +1 than max W/D */
maxD=8;
maxW=6;
maxH=ceil((shelfHigh)/shelfSpacing,0);
regalsteherDepth=18;
dachsteherDepth=50;
shelf2WallDist=regalsteherDepth+dachsteherDepth+metalThickness;
