/*  101 kippfenster cutout on left */
/*  110 kippfenster cutout on right */
/*  111 kippfenster cutout both sides */

pillars=[0];/* 0 default steher; >1 regal steher <0 no steher */
verticals=[0];
shelves=[0];
/* 0 free, <0 occupied area, other.addonId>0 docked */

for(i=0;i<(2*maxD+2*maxW);i=i+1){
pushBack(pillars,0);
pushBack(walls,100);
for(j=0;j<maxH;j=j+1){
pushBack(shelves,0);
}
for(k=0;k<4;k=k+1){
pushBack(panels,0);
}
for(l=0;l<10;l=l+1){
pushBack(verticals,0);
}
}
LENGTH_ARRAYS=2*maxD+2*maxW+1;

currentGroup='';
}/* end of init */

sizeW=substring(Size,0,1);
sizeD=substring(Size,1,1);
width=sizeW*1000;
depth=sizeD*1000;

panelGapStepping=4;

BEGIN_REARWALL=0;
END_REARWALL=sizeW;
BEGIN_FRONTWALL=maxW;
END_FRONTWALL=BEGIN_FRONTWALL+sizeW;
BEGIN_LEFTWALL=2*maxW;
END_LEFTWALL=BEGIN_LEFTWALL+sizeD;
BEGIN_RIGHTWALL=2*maxW+maxD;
END_RIGHTWALL=BEGIN_RIGHTWALL+sizeD;

showView=false;
showView2=false;

if(activeGroupInView()=='color_size_group'){
showView=false;
showView2=false;
if(currentGroup=='color_size_group'){
}else{
currentGroup='color_size_group';
view='all';
}
}

if(activeGroupInView()=='door_group'){
showView=false;
showView2=true;
if(currentGroup=='door_group'){
}else{
currentGroup='door_group';
view2='all';
}
}

if(activeGroupInView()=='foundation_group'){
showView=true;
showView2=false;
if(currentGroup=='foundation_group'){
}else{
currentGroup='foundation_group';
view='geoffnet';
}
}
if(activeGroupInView()=='extra_group'){
showView=true;
showView2=false;
if(currentGroup=='extra_group'){
}else{
currentGroup='extra_group';
view='roofless';
}
}

if(showView){
VISIBLE_REAR=in(view,'all','roofless','rear','geoffnet')||showDoorArea;
VISIBLE_FRONT=in(view,'all','roofless','front','geoffnet')||showDoorArea;
VISIBLE_LEFT=in(view,'all','roofless','left','geoffnet')||showDoorArea;
VISIBLE_RIGHT=in(view,'all','roofless','right','geoffnet')||showDoorArea;
DOOR_OPEN=(in(view,'geoffnet','roofless'))||showDoorArea;
VISIBLE_ARCHES=showDoorArea;
VISIBLE_ROOF=in(view,'all','geoffnet')&&(!showDoorArea);
}else{
VISIBLE_REAR=in(view2,'all','roofless','rear','geoffnet')||showDoorArea;
VISIBLE_FRONT=in(view2,'all','roofless','front','geoffnet')||showDoorArea;
VISIBLE_LEFT=in(view2,'all','roofless','left','geoffnet')||showDoorArea;
VISIBLE_RIGHT=in(view2,'all','roofless','right','geoffnet')||showDoorArea;
DOOR_OPEN=(in(view2,'geoffnet','roofless'))||showDoorArea;
VISIBLE_ARCHES=showDoorArea;
VISIBLE_ROOF=in(view2,'all','geoffnet')&&(!showDoorArea);
}

countOfRegalsteher=0;
for(i=0;i<LENGTH_ARRAYS;i=i+1){
if(get(pillars,i)>0){countOfRegalsteher=countOfRegalsteher+1;}
}

measurement_height=2500;
setBoxForMeasurement(Vector3f{width+280,depth+280,measurement_height+5},Vector3f{-150,-150,0});
