/* right*/
Copy();
RotateMatrixBy(Vector3f{0,0,1},Vector3f{width/2,-depth/2,0},180);
/* front*/
AddCube(Vector3f{width-100,50,40});
MoveMatrixBy(Vector3f{50,-50,-40});
/* rear*/
Copy();
