SetObjSurface('biohort:Alu-Bodenplatte');
SubComponent('Alu-Bodenplatten');
}
EndObjGroup();
MoveMatrixBy(Vector3f{0,depth,0});
}

/* REAR WALL */
if(VISIBLE_REAR){
BeginObjGroup('REARWALL');
for(i=BEGIN_REARWALL+1;i<END_REARWALL;i=i+1){
j=i;
wall=get(walls,j);
pillar=get(pillars,j);
if(wall==100){SubComponent('WALL_SOLID');RotateMatrixBy(Vector3f{0,0,1},Vector3f{500,metalThickness/2,0},180);MoveMatrixBy(Vector3f{-500+i*1000,0,0});}
if(wall==110){SubComponent('WALL_WINDOW_LEFT');RotateMatrixBy(Vector3f{0,0,1},Vector3f{500,metalThickness/2,0},180);MoveMatrixBy(Vector3f{-500+i*1000,0,0});}
if(wall==101){SubComponent('WALL_WINDOW_RIGHT');RotateMatrixBy(Vector3f{0,0,1},Vector3f{500,metalThickness/2,0},180);MoveMatrixBy(Vector3f{-500+i*1000,0,0});}
if(wall==111){SubComponent('WALL_WINDOW_BOTH');RotateMatrixBy(Vector3f{0,0,1},Vector3f{500,metalThickness/2,0},180);MoveMatrixBy(Vector3f{-500+i*1000,0,0});}
/*    if (pillar > -1) {
                    BeginObjGroup('PILLAR');
                        SubComponent('DACHSTEHER');
                        if (pillar > 0) {
                        SubComponent('REGALSTEHER');
                         MoveMatrixBy(Vector3f{0,dachsteherDepth,0});
                        }
                    EndObjGroup();
                     MoveMatrixBy(Vector3f{1000*i,metalThickness,0});
                    }       */
}
EndObjGroup();

/* rear wall glass */
