MoveMatrixBy(Vector3f{metalThickness-10,metalThickness+0.1,wallHeight});
}
/* REAR WALL END  */

/* FRONT WALL BEGIN*/
if(VISIBLE_FRONT){
BeginObjGroup('FRONTWALL');
for(i=1;i<sizeW;i=i+1){
j=i+BEGIN_FRONTWALL;
wall=get(walls,j);
pillar=get(pillars,j);
if(wall==100){SubComponent('WALL_SOLID');MoveMatrixBy(Vector3f{-500+i*1000,0,0});}
if(wall==110){SubComponent('WALL_WINDOW_LEFT');MoveMatrixBy(Vector3f{-500+i*1000,0,0});}
if(wall==101){SubComponent('WALL_WINDOW_RIGHT');MoveMatrixBy(Vector3f{-500+i*1000,0,0});}
if(wall==111){SubComponent('WALL_WINDOW_BOTH');MoveMatrixBy(Vector3f{-500+i*1000,0,0});}
