                    BeginObjGroup('PILLAR');
                        SubComponent('DACHSTEHER');
                        if (pillar > 0) {
                        SubComponent('REGALSTEHER');
                         MoveMatrixBy(Vector3f{0,dachsteherDepth,0});
                        }
                    EndObjGroup();
                     RotateMatrixBy(Vector3f{0,0,1},Vector3f{0,0,0},180);
                     MoveMatrixBy(Vector3f{1000*i + metalThickness,0,0});
                    }   */
}
EndObjGroup();
MoveMatrixBy(Vector3f{0,depth-metalThickness,0});

/* front wall glass */
AddCube(Vector3f{width-2*metalThickness+20,10,heightPillar-wallHeight});SetObjSurface('biohort:glass');
MoveMatrixBy(Vector3f{metalThickness-10,depth-metalThickness,wallHeight});

/* logo */
AddPlainCube(Vector3f{580,1,150},Vector2f{0.05,0.05},0,Vector2f{0,210});SetObjSurface('biohort:CasaNova_logo');
MoveMatrixBy(Vector3f{width-metalThickness-10-700,depth-metalThickness+11,wallHeight});
}
/* FRONT WALL END */

