if(VISIBLE_LEFT){
BeginObjGroup('LEFTWALL');
for(i=1;i<sizeD;i=i+1){
j=i+BEGIN_LEFTWALL;
wall=get(walls,j);
pillar=get(pillars,j);
if(wall==100){SubComponent('WALL_SOLID');RotateMatrixBy(Vector3f{0,0,1},Vector3f{0,0,0},90);MoveMatrixBy(Vector3f{metalThickness,-500+i*1000,0});}
if(wall==101){SubComponent('WALL_WINDOW_LEFT');RotateMatrixBy(Vector3f{0,0,1},Vector3f{0,0,0},90);MoveMatrixBy(Vector3f{metalThickness,-500+i*1000,0});}
if(wall==110){SubComponent('WALL_WINDOW_RIGHT');RotateMatrixBy(Vector3f{0,0,1},Vector3f{0,0,0},90);MoveMatrixBy(Vector3f{metalThickness,-500+i*1000,0});}
