SubComponent('REGALSTEHER');
MoveMatrixBy(Vector3f{0,dachsteherDepth,0});
RotateMatrixBy(Vector3f{0,0,1},Vector3f{0,0,0},270);
MoveMatrixBy(Vector3f{metalThickness,depth-metalThickness-30,0});
}
EndObjGroup();

/* left wall glass */
AddCube(Vector3f{10,depth-2*metalThickness-0.2,heightPillar-wallHeight});SetObjSurface('biohort:glass');
MoveMatrixBy(Vector3f{metalThickness-10-0.1,metalThickness+10+0.1,wallHeight});
}
/* LEFT WALL END */

