condition=VISIBLE_LEFT;
/* END OF SIDE-SPECIFIC */
if(other.dockId==(L*maxH+H)){condition=true;}else{
/* I feel sorry about this crap, but I'll rather do as small changes as possible considering the time we have */
if(other.addonName=='klapptisch'){condition=condition&&in(H,12,14,16)&&(!in(L,(BEGIN_LEFTWALL+2),(END_LEFTWALL+1)));}
if(other.addonName=='regalboden'){condition=condition&&in(H,12,16,20,24,28,32);}
if(other.addonName=='hakenset'){condition=condition&&in(H,22,28,34);}
pillarL=get(pillars,L-2);
pillarR=get(pillars,L-1);
condition=condition&&(pillarL>-1&&pillarR>-1)&&other.minimumDockHeight<=H;/* check if surrounding pillars can have regalsteher (which also means they are there and that means no window, door etc is there)  */
/* klapptisch specific: check if one is to the left and to the right */
if(other.addonId==10){
condition=condition&&(get(shelves,(L-1)*maxH+H)!=-10)&&(get(shelves,(L+1)*maxH+H)!=-10);
}
occupyStart=H-other.occupySpaceLow;if(occupyStart<0){occupyStart=0;}
occupyEnd=H+other.occupySpaceHigh;if(occupyEnd>maxH){occupyEnd=maxH;}
for(h=occupyStart;h<occupyEnd&&condition;h=h+1){
i=L*maxH+h;
if(get(shelves,i)!=0){condition=false;}/* search through shelves positions */
}
for(j=(L-2.5)*verticalsPerPanel;j<(L-0.5)*verticalsPerPanel-1&&condition;j=j+1){
if(get(verticals,j)==87){condition=false;}
}
for(j=(L-2)*verticalsPerPanel;j<(L-1)*verticalsPerPanel&&condition;j=j+1){
if(get(verticals,j)>0){condition=false;}
}

/* BIOH-159 */
if(hasTor==false){
if(condition&&L==BEGIN_LEFTWALL+1){
for(i=(BEGIN_REARWALL*verticalsPerPanel);i<(BEGIN_REARWALL*verticalsPerPanel+6);i=i+1){
if(get(verticals,i)>0){condition=false;}
}
}

if(condition&&L==END_LEFTWALL+1){
for(i=(BEGIN_FRONTWALL*verticalsPerPanel);i<(BEGIN_FRONTWALL*verticalsPerPanel+5);i=i+1){
if(get(verticals,i)>0){condition=false;}
}
}
}

}
